import type { EngineInterface, Register } from 'claude-code'

import {
  applyInput,
  cleanExplanation,
  explanationKey,
  explanationPrompt,
  fallbackExplanation,
  indentOf,
  isCodeFile,
  isFinished,
  isSkippedDir,
  pickSnippet,
  progressBar,
  relativePath,
  segments,
  shuffle,
  startPractice,
  stats,
  submitLine,
  typedPart,
} from './core.ts'
import type { Practice, Segment, Snippet } from './core.ts'

const PANE = 'code-typing-dojo'
const TITLE = '打字道場'
// The model that writes explanations: small and fast
const MODEL = 'haiku'
// How much of the project one pick may walk
const MAX_DIRS = 120
const MAX_DEPTH = 6
const MAX_FILES = 400
const FILES_TO_TRY = 8

type Explanation = { status: 'loading' | 'ready' | 'fallback'; text: string }

// What the pane shows, shared by the hooks below
let root = ''
let snippet: Snippet | null = null
let practice: Practice | null = null
let explanation: Explanation | null = null
let status: 'idle' | 'loading' | 'empty' | 'ready' = 'idle'
// Each pick gets a number, so a slow pick or explanation can't overwrite a newer one
let generation = 0

/** Lists the code files under the root, breadth first, skipping vendored and built directories. */
async function listCodeFiles($: EngineInterface, dir: string): Promise<string[]> {
  const files: string[] = []
  const queue: Array<{ path: string; depth: number }> = [{ path: dir, depth: 0 }]
  let dirs = 0
  while (queue.length > 0 && dirs < MAX_DIRS && files.length < MAX_FILES) {
    const { path, depth } = queue.shift()!
    dirs++
    let entries
    try {
      entries = await $.fs.list(path)
    } catch {
      continue
    }
    for (const entry of entries) {
      const full = path.replace(/[\\/]+$/, '') + '/' + entry.name
      if (entry.kind === 'dir') {
        if (depth < MAX_DEPTH && !isSkippedDir(entry.name)) queue.push({ path: full, depth: depth + 1 })
      } else if (entry.kind === 'file' && isCodeFile(entry.name, entry.size)) {
        files.push(full)
      }
    }
  }
  return files
}

/** Reads random code files until one holds a good snippet. */
async function findSnippet($: EngineInterface, dir: string): Promise<Snippet | null> {
  const files = shuffle(await listCodeFiles($, dir))
  for (const file of files.slice(0, FILES_TO_TRY)) {
    try {
      const text = await $.fs.read(file)
      if (typeof text !== 'string') continue
      const found = pickSnippet(text, relativePath(dir, file))
      if (found) return found
    } catch {
      // An unreadable file: try the next one
    }
  }
  return null
}

/** Gets the snippet's explanation from the store, or from a model, or falls back to a heuristic. */
async function explain($: EngineInterface, target: Snippet, gen: number): Promise<void> {
  const key = explanationKey(target)
  let text = ''
  try {
    const cached = await $.store.get(key)
    if (typeof cached === 'string' && cached !== '') text = cached
  } catch {
    // No store: ask the model
  }
  if (text === '') {
    try {
      const ask = explanationPrompt(target)
      const reply = await $.model.complete({
        model: MODEL,
        system: ask.system,
        prompt: ask.prompt,
        maxTokens: 300,
        timeoutMs: 30_000,
      })
      if (reply.isAnswered) text = cleanExplanation(reply.text)
      if (text !== '') await $.store.set(key, text)
    } catch {
      // A refused model or a failed write: fall back below
    }
  }
  if (gen !== generation) return
  explanation = text !== '' ? { status: 'ready', text } : { status: 'fallback', text: fallbackExplanation(target) }
  $.ui.invalidate('ui.render')
}

/** Picks a new snippet from the project and starts explaining it. */
async function loadSnippet($: EngineInterface): Promise<void> {
  const gen = ++generation
  status = 'loading'
  $.ui.invalidate('ui.render')
  let found: Snippet | null = null
  try {
    if (root === '') root = await $.session.cwd()
    found = await findSnippet($, root)
  } catch {
    found = null
  }
  if (gen !== generation) return
  snippet = found
  practice = found ? startPractice(found.lines) : null
  explanation = found ? { status: 'loading', text: '說明產生中…' } : null
  status = found ? 'ready' : 'empty'
  $.ui.invalidate('ui.render')
  if (found) await explain($, found, gen)
}

/** Starts the same snippet over. */
function restart($: EngineInterface): void {
  if (!snippet) return
  practice = startPractice(snippet.lines)
  $.ui.invalidate('ui.render')
}

const COLORS: Record<Segment['kind'], { color?: string; backgroundColor?: string; dimColor?: boolean }> = {
  correct: { color: 'green' },
  wrong: { color: 'white', backgroundColor: 'red' },
  extra: { color: 'white', backgroundColor: 'red' },
  pending: { dimColor: true },
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    root = e.cwd
    try {
      await $.command.register({ name: 'typing', description: '開啟打字道場（用專案程式碼練打字）', immediate: true })
      await $.command.register({ name: 'typing-next', description: '打字道場：換一段新的程式碼', immediate: true })
    } catch {
      // A name already taken: the pane still works from the other command
    }
    // Pick in the background, so the session starts at once
    void loadSnippet($)
    if (e.isInteractive) {
      try {
        const opened = await $.ui.open({ id: PANE, title: TITLE })
        if (!opened.isPlaced) $.ui.toast('打字練習已就緒，輸入 /typing 開啟')
      } catch {
        $.ui.toast('打字練習已就緒，輸入 /typing 開啟')
      }
    }
    return next(e)
  })

  on('command.run', { command: 'typing' }, async $ => {
    if (status === 'idle' || status === 'empty') void loadSnippet($)
    await $.ui.open({ id: PANE, title: TITLE, focus: true })
    return {}
  })

  on('command.run', { command: 'typing-next' }, async $ => {
    await $.ui.open({ id: PANE, title: TITLE, focus: true })
    await loadSnippet($)
    return snippet ? { text: '已換新片段：' + snippet.path + ':' + snippet.startLine + '-' + snippet.endLine } : { text: '找不到適合練習的程式碼檔案。' }
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const elements = $.ui.resolve(e)
    const { Box, Text, Button } = elements
    // Mobile has no text field, so practice there isn't possible
    const Input = e.surface !== 'mobile' && 'Input' in elements ? elements.Input : null
    const now = await $.clock.now()

    const nextButton = (isFocused: boolean) =>
      Button({
        key: 'next',
        label: '下一段',
        hotkey: 'n',
        plain: true,
        ...(isFocused ? { autoFocus: true as const } : {}),
        onPress: () => loadSnippet($),
      })
    const restartButton = Button({ key: 'restart', label: '重新開始', hotkey: 'r', plain: true, onPress: () => restart($) })
    const header = Text({ bold: true, color: 'claude', children: ['⌨  程式碼打字道場'] })

    if (status !== 'ready' || !snippet || !practice) {
      const message =
        status === 'empty' ? '這個專案裡找不到適合練習的程式碼檔案。' : '正在從專案挑選程式碼…'
      return Box({
        flexDirection: 'column',
        children: [header, Text({ dimColor: true, children: [message] }), nextButton(status === 'empty')],
      })
    }

    const p = practice
    const s = stats(p, now)
    const done = isFinished(p)
    const width = String(snippet.endLine).length

    // One row for each line: its number, a marker for the current line, then the colored text
    const rows = p.lines.map((line, i) => {
      const isCurrent = i === p.done.length && !done
      const typed = i < p.done.length ? p.done[i] : isCurrent ? p.current : ''
      const parts = segments(typedPart(line), typed).map(seg => Text({ ...COLORS[seg.kind], children: [seg.text] }))
      const gutter = String(snippet!.startLine + i).padStart(width, ' ')
      return Text({
        wrap: 'truncate-end',
        children: [
          Text({ ...(isCurrent ? { color: 'claude' } : { dimColor: true }), children: [(isCurrent ? '›' : ' ') + gutter + ' '] }),
          indentOf(line),
          ...parts,
        ],
      })
    })

    const statLine = Text({
      children: [
        'WPM ' + s.wpm + ' · 正確率 ' + s.accuracy + '% · 進度 ' + progressBar(s.linesDone, s.linesTotal) + ' ' + s.linesDone + '/' + s.linesTotal,
      ],
    })

    const field = done
      ? Box({
          key: 'result',
          flexDirection: 'column',
          borderStyle: 'round',
          paddingX: 1,
          children: [
            Text({ bold: true, color: 'success', children: ['🎉 完成！'] }),
            Text({ children: ['速度 ' + s.wpm + ' WPM，正確率 ' + s.accuracy + '%，用時 ' + s.seconds + ' 秒'] }),
            Text({ dimColor: true, children: ['正確字元 ' + s.correct + ' / ' + s.typed + '。按 n 換下一段，r 再練一次。'] }),
          ],
        })
      : !Input
        ? Text({ dimColor: true, children: ['這個介面無法輸入文字，請在終端機或 Claude Desktop 練習。'] })
        : Input({
          key: 'typing',
          label: '輸入',
          placeholder: typedPart(p.lines[p.done.length]),
          value: p.current,
          submitLabel: '下一行',
          autoFocus: true,
          onInput: async (value: string) => {
            const at = await $.clock.now()
            if (practice) practice = applyInput(practice, value, at)
            $.ui.invalidate('ui.render')
          },
          onSubmit: async (value: string) => {
            const at = await $.clock.now()
            if (practice) practice = submitLine(practice, value, at)
            $.ui.invalidate('ui.render')
          },
        })

    return Box({
      flexDirection: 'column',
      children: [
        header,
        Text({ dimColor: true, wrap: 'truncate-start', children: [snippet.path + ':' + snippet.startLine + '-' + snippet.endLine] }),
        Text({ children: [' '] }),
        ...rows,
        Text({ children: [' '] }),
        field,
        statLine,
        Text({ children: [' '] }),
        Text({ bold: true, children: ['說明'] }),
        Text({ dimColor: explanation?.status === 'loading', children: [explanation?.text ?? ''] }),
        Text({ children: [' '] }),
        Box({ flexDirection: 'row', columnGap: 3, children: [nextButton(done), restartButton] }),
        Text({ dimColor: true, children: ['Tab 切到按鈕 · Esc 回到提示列 · Ctrl+X X 關閉'] }),
      ],
    })
  })
}

