// Pure logic for code-typing-dojo: picking snippets, scoring, highlighting.
// No `$` here, so tests can call every function directly.

export const SKIP_DIRS = new Set([
  'node_modules', '.git', 'dist', 'build', 'vendor', '.claude', '.claude-plugin',
  '.next', '.nuxt', 'out', 'coverage', 'target', '__pycache__', '.venv', 'venv',
  '.idea', '.vscode', '.cache', 'bower_components', '.svn', '.hg', 'tmp',
])

export const CODE_EXTS = new Set([
  'js', 'mjs', 'cjs', 'jsx', 'ts', 'mts', 'cts', 'tsx', 'py', 'php', 'go', 'rs', 'rb',
  'java', 'kt', 'swift', 'c', 'h', 'cc', 'cpp', 'hpp', 'cs', 'css', 'scss', 'sh',
  'bash', 'zsh', 'lua', 'dart', 'scala', 'ex', 'exs', 'vue', 'svelte', 'sql', 'pl', 'r',
])

const LOCKFILES = new Set([
  'package-lock.json', 'yarn.lock', 'pnpm-lock.yaml', 'composer.lock', 'Cargo.lock',
  'Gemfile.lock', 'poetry.lock', 'go.sum', 'bun.lockb', 'Pipfile.lock',
])

export const MAX_FILE_BYTES = 200_000
export const MIN_LINES = 3
export const MAX_LINES = 12
export const PREFERRED_WIDTH = 60
export const MAX_WIDTH = 80

export type Snippet = {
  /** Path relative to the project root, with `/` separators. */
  path: string
  /** 1-based line numbers in the file, inclusive. */
  startLine: number
  endLine: number
  /** The lines to type, dedented, tabs as two spaces, no trailing spaces. */
  lines: string[]
}

export type Segment = { text: string; kind: 'correct' | 'wrong' | 'pending' | 'extra' }

export type Practice = {
  lines: string[]
  /** What was typed for each finished line. */
  done: string[]
  /** The text in the field for the current line. */
  current: string
  startedAt: number | null
  finishedAt: number | null
}

export type Stats = {
  correct: number
  typed: number
  wpm: number
  accuracy: number
  linesDone: number
  linesTotal: number
  isFinished: boolean
  seconds: number
}

/** The extension of a file name, lower case, without the dot. */
export function extOf(name: string): string {
  const dot = name.lastIndexOf('.')
  return dot <= 0 ? '' : name.slice(dot + 1).toLowerCase()
}

/** Whether a directory entry should not be walked into. */
export function isSkippedDir(name: string): boolean {
  return SKIP_DIRS.has(name) || (name.startsWith('.') && name !== '.')
}

/** Whether a file looks like source code worth practicing on. */
export function isCodeFile(name: string, size: number): boolean {
  if (LOCKFILES.has(name)) return false
  if (/\.min\.(js|css)$/i.test(name) || /\.(bundle|chunk)\.js$/i.test(name)) return false
  if (/\.d\.ts$/i.test(name)) return false
  if (size <= 0 || size > MAX_FILE_BYTES) return false
  return CODE_EXTS.has(extOf(name))
}

/** Whether text read from a file is binary or minified, and so not worth typing. */
export function looksUnusable(text: string): boolean {
  if (text.includes('\u0000')) return true
  const lines = text.split('\n')
  if (lines.some(line => line.length > 400)) return true
  const avg = text.length / Math.max(1, lines.length)
  return avg > 160
}

/** Tabs to two spaces, trailing whitespace trimmed, CR dropped. */
export function normalizeLine(line: string): string {
  return line.replace(/\r$/, '').replace(/\t/g, '  ').replace(/\s+$/, '')
}

const DEFINITION = new RegExp(
  [
    String.raw`^\s*(export\s+)?(default\s+)?(async\s+)?function\b`,
    String.raw`^\s*(export\s+)?(default\s+)?(abstract\s+)?class\b`,
    String.raw`^\s*(export\s+)?(const|let|var)\s+\w+\s*=\s*(async\s+)?(\([^)]*\)|\w+)\s*=>`,
    String.raw`^\s*(export\s+)?(interface|type|enum)\s+\w+`,
    String.raw`^\s*(async\s+)?def\s+\w+`,
    String.raw`^\s*class\s+\w+`,
    String.raw`^\s*func\s+`,
    String.raw`^\s*(pub\s+)?(async\s+)?fn\s+\w+`,
    String.raw`^\s*(pub\s+)?(struct|impl|trait)\b`,
    String.raw`^\s*(public|private|protected|static)\s+[\w<>\[\],\s]*\w+\s*\(`,
    String.raw`^\s*(public\s+|private\s+|protected\s+)?(static\s+)?function\s+\w+`,
    String.raw`^\s*def\s+\w+`,
    String.raw`^\s*module\s+\w+`,
    String.raw`^\s*[\w-]+\s*\(\)\s*\{`,
    String.raw`^\s*(async\s+)?[a-zA-Z_]\w*\s*\([^)]*\)\s*\{\s*$`,
    String.raw`^[.#]?[\w-][\w\s.#:>,-]*\{\s*$`,
  ].join('|'),
)

/** Whether a line opens a function, class or similar definition. */
export function isDefinition(line: string): boolean {
  if (/^\s*(if|for|while|switch|catch|else|return)\b/.test(line)) return false
  return DEFINITION.test(line)
}

/** Whether a line has something to type: not blank, not just a brace or a comment. */
export function isMeaningful(line: string): boolean {
  const t = line.trim()
  if (t === '') return false
  if (/^[{}()\[\];,]+$/.test(t)) return false
  return !/^(\/\/|#(?!include)|\/\*|\*|--|<!--)/.test(t)
}

/** Removes the indentation every non-blank line shares. */
export function dedent(lines: string[]): string[] {
  const indents = lines.filter(l => l.trim() !== '').map(l => l.length - l.trimStart().length)
  const cut = indents.length > 0 ? Math.min(...indents) : 0
  return lines.map(l => l.slice(cut))
}

type Candidate = { start: number; end: number; lines: string[]; score: number }

/**
 * The block starting at `start`: up to MAX_LINES consecutive lines, ending
 * before a blank line. `end` is the index of its last line.
 */
function blockAt(all: string[], start: number): { lines: string[]; end: number } {
  const out: string[] = []
  for (let i = start; i < all.length && out.length < MAX_LINES; i++) {
    if (all[i].trim() === '') break
    out.push(all[i])
  }
  // Drop a trailing comment, but keep a closing brace
  while (out.length > MIN_LINES && !isMeaningful(out[out.length - 1])) {
    if (/^[}\])]+[;,)]*$/.test(out[out.length - 1].trim())) break
    out.pop()
  }
  return { lines: out, end: start + out.length - 1 }
}

function scoreBlock(lines: string[], isDef: boolean): number {
  if (lines.length < MIN_LINES) return -1
  const widths = lines.map(l => l.length)
  if (widths.some(w => w > MAX_WIDTH)) return -1
  const meaningful = lines.filter(isMeaningful).length
  if (meaningful < 2) return -1
  let score = meaningful
  if (isDef) score += 10
  score -= widths.filter(w => w > PREFERRED_WIDTH).length * 3
  if (lines.length >= 4 && lines.length <= 10) score += 2
  return score
}

/**
 * Picks a snippet of 3 to 12 consecutive lines from a file's text, preferring
 * one that starts at a definition and keeps lines short. `random` returns a
 * number in [0, 1), so tests can make the pick deterministic.
 */
export function pickSnippet(text: string, path: string, random: () => number = Math.random): Snippet | null {
  if (looksUnusable(text)) return null
  // Keep blank lines as they are so line numbers stay the file's own
  const all = text.split('\n').map(normalizeLine)
  const candidates: Candidate[] = []
  for (let i = 0; i < all.length; i++) {
    if (!isMeaningful(all[i])) continue
    const isDef = isDefinition(all[i])
    // A non-definition start only at the top of a run of code, to keep the list small
    if (!isDef && i > 0 && all[i - 1].trim() !== '') continue
    const block = blockAt(all, i)
    const score = scoreBlock(block.lines, isDef)
    if (score > 0) candidates.push({ start: i, end: block.end, lines: block.lines, score })
  }
  if (candidates.length === 0) return null
  const best = Math.max(...candidates.map(c => c.score))
  // Choose among the good ones, not only the very best, so snippets vary
  const good = candidates.filter(c => c.score >= best - 4)
  const chosen = good[Math.min(good.length - 1, Math.floor(random() * good.length))]
  return { path, startLine: chosen.start + 1, endLine: chosen.end + 1, lines: dedent(chosen.lines) }
}

/** FNV-1a hash of a string, as eight hex digits. */
export function hashText(text: string): string {
  let h = 0x811c9dc5
  for (let i = 0; i < text.length; i++) {
    h ^= text.charCodeAt(i)
    h = Math.imul(h, 0x01000193) >>> 0
  }
  return h.toString(16).padStart(8, '0')
}

/** The `$.store` key for a snippet's explanation. */
export function explanationKey(snippet: Snippet): string {
  return 'explain:' + snippet.path + ':' + hashText(snippet.lines.join('\n'))
}

/** The name of the first function, class or method in a snippet, if any. */
export function detectName(lines: string[]): { kind: string; name: string } | null {
  const patterns: Array<[RegExp, string]> = [
    [/\bclass\s+([A-Za-z_$][\w$]*)/, '類別'],
    [/\bfunction\s*\*?\s*([A-Za-z_$][\w$]*)/, '函式'],
    [/\b(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=\s*(?:async\s+)?(?:\([^)]*\)|[A-Za-z_$][\w$]*)\s*=>/, '函式'],
    [/\bdef\s+([A-Za-z_]\w*)/, '函式'],
    [/\bfn\s+([A-Za-z_]\w*)/, '函式'],
    [/\bfunc\s+(?:\([^)]*\)\s*)?([A-Za-z_]\w*)/, '函式'],
    [/\b(?:interface|type|enum|struct|trait)\s+([A-Za-z_]\w*)/, '型別'],
    [/^\s*(?:async\s+)?([A-Za-z_$][\w$]*)\s*\([^)]*\)\s*\{/, '方法'],
  ]
  for (const line of lines) {
    for (const [re, kind] of patterns) {
      const m = re.exec(line)
      if (m) return { kind, name: m[1] }
    }
  }
  return null
}

/** The explanation shown when the model can't give one. */
export function fallbackExplanation(snippet: Snippet): string {
  const file = snippet.path.split('/').pop() || snippet.path
  const found = detectName(snippet.lines)
  const where = '這段程式碼來自 ' + file + ' 第 ' + snippet.startLine + '–' + snippet.endLine + ' 行'
  return found ? where + '，定義了' + found.kind + '「' + found.name + '」。' : where + '。'
}

/** The prompt that asks a model to explain a snippet. */
export function explanationPrompt(snippet: Snippet): { system: string; prompt: string } {
  return {
    system:
      '你是親切的程式教學助理。請用繁體中文（台灣用語），以一到三句話、初學者看得懂的方式，說明使用者給的程式碼片段在做什麼。只輸出說明文字，不要使用 Markdown、程式碼區塊或條列。',
    prompt: '檔案：' + snippet.path + '\n\n' + snippet.lines.join('\n'),
  }
}

/** Cleans a model's reply into one short paragraph. */
export function cleanExplanation(text: string): string {
  return text
    .replace(/```[\s\S]*?```/g, '')
    .replace(/[*_`#>]/g, '')
    .replace(/\s*\n+\s*/g, ' ')
    .trim()
    .slice(0, 400)
}

/** The part of a line to type: the line without its leading indentation. */
export function typedPart(line: string): string {
  return line.trimStart()
}

/** The indentation of a line, drawn but not typed. */
export function indentOf(line: string): string {
  return line.slice(0, line.length - line.trimStart().length)
}

/**
 * Splits a target into runs by how the typed text compares: `correct` and
 * `wrong` for typed characters, `pending` for the rest of the target, and
 * `extra` for typed characters past its end.
 */
export function segments(target: string, typed: string): Segment[] {
  const out: Segment[] = []
  const push = (text: string, kind: Segment['kind']) => {
    const last = out[out.length - 1]
    if (last && last.kind === kind) last.text += text
    else out.push({ text, kind })
  }
  const n = Math.max(target.length, typed.length)
  for (let i = 0; i < n; i++) {
    if (i >= typed.length) push(target[i], 'pending')
    else if (i >= target.length) push(typed[i], 'extra')
    else push(target[i], typed[i] === target[i] ? 'correct' : 'wrong')
  }
  return out
}

/** Correct characters, and characters counted, for one line. */
export function scoreLine(target: string, typed: string, isSubmitted: boolean): { correct: number; total: number } {
  let correct = 0
  for (let i = 0; i < typed.length && i < target.length; i++) {
    if (typed[i] === target[i]) correct++
  }
  // A submitted line also counts the characters it left out as misses
  const total = isSubmitted ? Math.max(typed.length, target.length) : typed.length
  return { correct, total }
}

export function startPractice(lines: string[]): Practice {
  return { lines: [...lines], done: [], current: '', startedAt: null, finishedAt: null }
}

export function isFinished(p: Practice): boolean {
  return p.done.length >= p.lines.length
}

/** The practice after the field's text changed; the clock starts at the first keystroke. */
export function applyInput(p: Practice, value: string, now: number): Practice {
  if (isFinished(p)) return p
  const startedAt = p.startedAt ?? (value.length > 0 ? now : null)
  return { ...p, current: value, startedAt }
}

/** The practice after Enter: the line is kept as typed and the next one starts. */
export function submitLine(p: Practice, value: string, now: number): Practice {
  if (isFinished(p)) return p
  const done = [...p.done, value]
  const startedAt = p.startedAt ?? now
  const finishedAt = done.length >= p.lines.length ? now : null
  return { ...p, done, current: '', startedAt, finishedAt }
}

export function stats(p: Practice, now: number): Stats {
  let correct = 0
  let typed = 0
  p.done.forEach((value, i) => {
    const s = scoreLine(typedPart(p.lines[i]), value, true)
    correct += s.correct
    typed += s.total
  })
  if (!isFinished(p)) {
    const s = scoreLine(typedPart(p.lines[p.done.length]), p.current, false)
    correct += s.correct
    typed += s.total
  }
  const end = p.finishedAt ?? now
  const ms = p.startedAt === null ? 0 : Math.max(0, end - p.startedAt)
  const minutes = ms / 60_000
  const wpm = minutes > 0 ? Math.round(correct / 5 / minutes) : 0
  const accuracy = typed > 0 ? Math.round((correct / typed) * 100) : 100
  return {
    correct,
    typed,
    wpm,
    accuracy,
    linesDone: p.done.length,
    linesTotal: p.lines.length,
    isFinished: isFinished(p),
    seconds: Math.round(ms / 1000),
  }
}

/** A text progress bar such as `███░░░`. */
export function progressBar(done: number, total: number, width = 12): string {
  const filled = total > 0 ? Math.round((done / total) * width) : 0
  return '█'.repeat(filled) + '░'.repeat(width - filled)
}

/** A copy of the items in random order. */
export function shuffle<T>(items: readonly T[], random: () => number = Math.random): T[] {
  const out = [...items]
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.floor(random() * (i + 1))
    ;[out[i], out[j]] = [out[j], out[i]]
  }
  return out
}

/** A path relative to the root, with `/` separators. */
export function relativePath(root: string, full: string): string {
  const r = root.replace(/[\\/]+$/, '')
  const rel = full.startsWith(r) ? full.slice(r.length).replace(/^[\\/]+/, '') : full
  return rel.replace(/\\/g, '/')
}

